USER_SCRIPT="$ErrorActionPreference='Stop'\n$out='@OUT@'\nfunction Get-PendingSafeSample {\n$ErrorActionPreference='Stop'\ntry{\n if([Security.Principal.WindowsIdentity]::GetCurrent().IsSystem){throw 'USER_CONTEXT_REQUIRED'}\n $task=Get-ScheduledTask -TaskName 'HARA Commander Agent'\n $sid=[string]$task.Principal.UserId\n if($sid -notmatch '^S-1-'){$sid=(New-Object Security.Principal.NTAccount($sid)).Translate([Security.Principal.SecurityIdentifier]).Value}\n $root=Join-Path $env:LOCALAPPDATA 'HARA Commander'\n $pending=Join-Path $root 'pending-action-approval.json'\n $reply=Join-Path $root 'action-approval-response.json'\n $session=Join-Path $root 'operator-session.json'\n $source=Join-Path $root 'hara-commander-agent.ps1'\n $exists=Test-Path -LiteralPath $pending -PathType Leaf\n $active=$false;$future=$false;$remaining=0;$ownerAlive=$false;$consumerAlive=$false;$source48=$false\n $source48=((Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash.ToLowerInvariant() -ceq 'f54e5ff8c170e09a3dc795004af426851d111c89ae78408559886e0d693bf805')\n if($exists -and $source48 -and [string]$task.State -ceq 'Running' -and -not(Test-Path -LiteralPath $reply) -and (Test-Path -LiteralPath $session)){\n  $before=(Get-FileHash -LiteralPath $pending -Algorithm SHA256).Hash\n  $p=Get-Content -LiteralPath $pending -Raw|ConvertFrom-Json\n  $s=Get-Content -LiteralPath $session -Raw|ConvertFrom-Json\n  $until=[DateTime]::Parse([string]$p.expires_at_utc).ToUniversalTime()\n  $remaining=[Math]::Max(0,[int][Math]::Floor(($until-[DateTime]::UtcNow).TotalMilliseconds))\n  $future=$remaining -gt 0\n  $op=Get-Process -Id ([int]$p.owner_pid) -ErrorAction SilentlyContinue\n  $worker=Get-Process -Id ([int]$p.consumer_pid) -ErrorAction SilentlyContinue\n  if($op -and $worker -and $op.Id -eq 8184 -and $worker.Id -ne $op.Id){\n   $os=$op.StartTime;$ws=$worker.StartTime\n   if($os -is [DateTime] -and $ws -is [DateTime]){\n    $ownerAlive=($os.ToUniversalTime().ToString('o') -ceq '2026-10-12T17:23:02.2031480Z' -and $os.ToUniversalTime().ToString('o') -ceq [string]$p.owner_started_at_utc -and [int]$s.owner_pid -eq [int]$p.owner_pid -and [string]$s.owner_started_at_utc -ceq [string]$p.owner_started_at_utc)\n    $consumerAlive=($ws.ToUniversalTime().ToString('o') -ceq [string]$p.consumer_started_at_utc)\n    foreach($pidToCheck in @([int]$p.owner_pid,[int]$p.consumer_pid)){\n     $c=Get-CimInstance Win32_Process -Filter ('ProcessId='+$pidToCheck) -ErrorAction Stop\n     $o=Invoke-CimMethod -InputObject $c -MethodName GetOwnerSid -ErrorAction Stop\n     if([int]$o.ReturnValue -ne 0 -or [string]$o.Sid -cne $sid -or ([int]$pidToCheck -eq [int]$p.consumer_pid -and ([string]$c.CommandLine).IndexOf((Join-Path $root 'hara-commander-agent.ps1'),[StringComparison]::OrdinalIgnoreCase) -lt 0)){$ownerAlive=$false;$consumerAlive=$false}\n    }\n   }\n  }\n  $unchanged=(Test-Path -LiteralPath $pending) -and (Get-FileHash -LiteralPath $pending -Algorithm SHA256).Hash -ceq $before\n  $active=([string]$p.request_id -ceq 'HARA-CUSTOMER-MCP-1x-I9N9VadESKSpV-hz3pqREnFr-UN7O9bqJDNiFCmg' -and $future -and $ownerAlive -and $consumerAlive -and $unchanged -and [string]$p.schema -ceq 'hara.commander-local-action-approval.v1')\n }\n [pscustomobject]@{state='READ_ONLY';pending_exists=[bool]$exists;pending_active=[bool]$active;expires_in_future=[bool]$future;remaining_ms=[int]$remaining;expires_at_utc=if($active){$until.ToString('o')}else{''};observed_at_utc=[DateTime]::UtcNow.ToString('o');owner_alive_and_bound=[bool]$ownerAlive;consumer_alive_and_bound=[bool]$consumerAlive;source48_pinned=[bool]$source48;task_running=([string]$task.State -ceq 'Running');approval_generated=$false;private_values_exposed=$false}\n}catch{\n [pscustomobject]@{state='READ_ONLY_ERROR';pending_active=$false;reason='PENDING_METADATA_UNAVAILABLE';approval_generated=$false;private_values_exposed=$false}\n}\n}\n$clock=[Diagnostics.Stopwatch]::StartNew()\nwhile($clock.ElapsedMilliseconds -lt 60000){$m=Get-PendingSafeSample;$tmp=$out+'.tmp';[IO.File]::WriteAllText($tmp,($m|ConvertTo-Json -Compress),(New-Object Text.UTF8Encoding($false)));if(Test-Path -LiteralPath $out){[IO.File]::Replace($tmp,$out,$null,$true)}else{[IO.File]::Move($tmp,$out)};Start-Sleep -Milliseconds 100}\n"
def emit(v):print(json.dumps(v,sort_keys=True))
